// SPDX-License-Identifier: MIT
pragma solidity ^0.8.17;

import "@openzeppelin/contracts/access/AccessControl.sol";

/// @title  KeyRegistry with shared manager roles
/// @notice Allows multiple managers (e.g., Manufacturer & Local Server) to add/revoke AES key IDs
contract KeyRegistry is AccessControl {
    /// @dev Role identifier for managers
    bytes32 public constant MANAGER_ROLE = keccak256("MANAGER_ROLE");

    struct KeyMeta {
        bytes32 keyHash;    // SHA‑256 of AES‑key
        uint256 created;
        bool    revoked;
    }

    /// @notice Mapping from keyID to metadata
    mapping(bytes32 => KeyMeta) public keys;

    /// @notice Emitted when a new keyID is added
    event NewKey(bytes32 indexed keyID, bytes32 keyHash);

    /// @notice Emitted when a keyID is revoked
    event RevokeKey(bytes32 indexed keyID);

    /**
     * @param manufacturer  Initial manager and default admin
     * @param localServer   Second manager
     */
    constructor(address manufacturer, address localServer) {
        // Grant DEFAULT_ADMIN_ROLE to manufacturer (can grant/revoke roles)
        _grantRole(DEFAULT_ADMIN_ROLE, manufacturer);
        // Both addresses get manager permissions
        _grantRole(MANAGER_ROLE,       manufacturer);
        _grantRole(MANAGER_ROLE,       localServer);
    }

    /// @notice Add a new AES-group-key identifier
    /// @dev Only addresses with MANAGER_ROLE may call
    /// @param keyID     Identifier = keccak256(aesGroupKey)
    /// @param keyHash   SHA-256(aesGroupKey)
    function addKey(bytes32 keyID, bytes32 keyHash)
        external
        onlyRole(MANAGER_ROLE)
    {
        require(keys[keyID].created == 0, "KeyRegistry: key exists");
        keys[keyID] = KeyMeta(keyHash, block.timestamp, false);
        emit NewKey(keyID, keyHash);
    }

    /// @notice Revoke an existing AES-group-key identifier
    /// @dev Only addresses with MANAGER_ROLE may call
    /// @param keyID  Identifier to revoke
    function revokeKey(bytes32 keyID)
        external
        onlyRole(MANAGER_ROLE)
    {
        KeyMeta storage m = keys[keyID];
        require(m.created != 0, "KeyRegistry: not found");
        require(!m.revoked,   "KeyRegistry: already revoked");
        m.revoked = true;
        emit RevokeKey(keyID);
    }
}

